  ('usec-bio-006', 1, 'in_review', array['upper_secondary']::text[], 'biology', 'Transport', 'Red blood cells', 3, 'remember', 'true_false', 'True or false: mature human red blood cells have no nucleus.', null, null, 'Relate the structure of red blood cells to their function.', 'Upper secondary biology: transport in humans (e.g. KSSM Biologi Tingkatan 4 / SPM).', '{"system":"KSSM","subject":"Biologi","years":[4]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('usec-bio-007', 1, 'in_review', array['upper_secondary']::text[], 'biology', 'Coordination', 'Hormones', 3, 'remember', 'matching', 'Match each hormone to the gland that makes it.', '{"left":[{"id":"a","text":"Insulin"},{"id":"b","text":"Adrenaline"},{"id":"c","text":"Thyroxine"}],"right":[{"id":"x","text":"Thyroid gland"},{"id":"y","text":"Pancreas"},{"id":"z","text":"Adrenal gland"}]}'::jsonb, null, 'Identify endocrine glands and their hormones.', 'Upper secondary biology: endocrine system (e.g. KSSM Biologi Tingkatan 4 / SPM).', '{"system":"KSSM","subject":"Biologi","years":[4]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('usec-bio-008', 1, 'in_review', array['upper_secondary']::text[], 'biology', 'Cell membrane', 'Osmosis', 2, 'remember', 'short_answer', 'What is the movement of water molecules across a partially permeable membrane, from a dilute solution to a more concentrated one, called?', null, null, 'Define osmosis.', 'Upper secondary biology: movement of substances across membranes (e.g. KSSM Biologi Tingkatan 4 / SPM).', '{"system":"KSSM","subject":"Biologi","years":[4]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('usec-hist-001', 1, 'in_review', array['upper_secondary']::text[], 'history', 'Independence', 'Independence of Malaya', 1, 'remember', 'mcq', 'On what date did the Federation of Malaya gain independence?', '[{"id":"a","text":"31 August 1957"},{"id":"b","text":"16 September 1963"},{"id":"c","text":"1 February 1948"},{"id":"d","text":"9 August 1965"}]'::jsonb, null, 'Recall key dates in Malaysia''s history.', 'Upper secondary history: independence (e.g. KSSM Sejarah Tingkatan 4 / SPM).', '{"system":"KSSM","subject":"Sejarah","years":[4]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('usec-hist-002', 1, 'in_review', array['upper_secondary']::text[], 'history', 'Formation of Malaysia', 'Year of formation', 1, 'remember', 'numeric', 'In which year was Malaysia formed?', null, null, 'Recall key dates in Malaysia''s history.', 'Upper secondary history: formation of Malaysia (e.g. KSSM Sejarah Tingkatan 5 / SPM).', '{"system":"KSSM","subject":"Sejarah","years":[5]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('usec-hist-003', 1, 'in_review', array['upper_secondary']::text[], 'history', 'Independence', 'Leaders', 1, 'remember', 'mcq', 'Who was the first Prime Minister of Malaysia?', '[{"id":"a","text":"Tunku Abdul Rahman"},{"id":"b","text":"Tun Abdul Razak"},{"id":"c","text":"Tun Hussein Onn"},{"id":"d","text":"Tun Dr Mahathir Mohamad"}]'::jsonb, null, 'Identify key figures in Malaysia''s history.', 'Upper secondary history: independence (e.g. KSSM Sejarah Tingkatan 4 / SPM).', '{"system":"KSSM","subject":"Sejarah","years":[4]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('usec-hist-004', 1, 'in_review', array['upper_secondary']::text[], 'history', 'Formation of Malaysia', 'Timeline', 2, 'understand', 'ordering', 'Put these events in the order they happened, earliest first.', '[{"id":"a","text":"Malaysia is formed"},{"id":"b","text":"The Federation of Malaya is set up"},{"id":"c","text":"Singapore leaves Malaysia"},{"id":"d","text":"Malaya gains independence"}]'::jsonb, null, 'Sequence key events in Malaysia''s history.', 'Upper secondary history: independence and formation of Malaysia (e.g. KSSM Sejarah Tingkatan 4–5 / SPM).', '{"system":"KSSM","subject":"Sejarah","years":[4,5]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0')
insert into public.question_keys (question_id, answer, explanation, wrong, mistakes) values
  ('usec-math-001', '["a","b"]'::jsonb, 'Factorise: x² − 5x + 6 = (x − 2)(x − 3) = 0, so x = 2 or x = 3.', '{"c":"Check: (−2)² − 5(−2) + 6 = 20, not 0. The signs flip when you read the roots from (x − 2)(x − 3).","d":"Check: (−3)² − 5(−3) + 6 = 30, not 0.","e":"6 is the constant term; 6² − 30 + 6 = 12, not 0."}'::jsonb, null),
  ('usec-math-002', '{"value":17,"tolerance":0}'::jsonb, 'n(A ∪ B) = n(A) + n(B) − n(A ∩ B) = 12 + 9 − 4 = 17. The 4 shared elements would otherwise be counted twice.', null, '[{"value":21,"why":"21 counts the 4 shared elements twice; subtract n(A ∩ B)."},{"value":13,"why":"Subtract the overlap only once: 12 + 9 − 4 = 17."}]'::jsonb),
  ('usec-math-003', '"a"'::jsonb, 'Place values from the right are 1, 2, 4, 8: 1×8 + 1×4 + 0×2 + 1×1 = 13.', '{"b":"11 is 1011₂: the 1s are in different places.","c":"26 is 11010₂, every digit shifted one place left.","d":"4 is how many digits there are, not the value."}'::jsonb, null),
  ('usec-math-004', '"false"'::jsonb, 'The converse is "If x² = 9, then x = 3". It is false because x could also be −3.', '{"true":"A statement being true does not make its converse true. One counter-example (x = −3) is enough to show the converse is false."}'::jsonb, null),
  ('usec-math-005', '{"value":2,"tolerance":0}'::jsonb, 'Divide everything by 2 to get y = mx + c form: y = 2x + 3. The gradient m is 2.', null, '[{"value":4,"why":"Make y the subject first: divide the whole equation by 2."},{"value":3,"why":"3 is the y-intercept, not the gradient."}]'::jsonb),
  ('usec-math-006', '"a"'::jsonb, 'On the y-axis x = 0, so y = 3(0) − 5 = −5. The point is (0, −5).', '{"b":"3 is the gradient, not the intercept.","c":"This point is on the x-axis, and does not lie on the line.","d":"(5/3, 0) is where the line crosses the x-axis."}'::jsonb, null),
  ('usec-math-007', '{"value":21,"tolerance":0}'::jsonb, 'y = kx. From 12 = k × 4, k = 3. So y = 3 × 7 = 21.', null, '[{"value":15,"why":"15 adds 3 to 12; direct variation multiplies by the constant k = 3."}]'::jsonb),
  ('usec-math-008', '{"value":2,"tolerance":0.01}'::jsonb, 'Mean = 40 ÷ 8 = 5. Squared deviations: 9, 1, 1, 1, 0, 0, 4, 16, which total 32. Variance = 32 ÷ 8 = 4, so the standard deviation = √4 = 2.', null, '[{"value":4,"why":"4 is the variance; take its square root."},{"value":5,"why":"5 is the mean, a measure of centre, not spread."}]'::jsonb),
  ('usec-math-009', '{"a":"y","b":"z","c":"x"}'::jsonb, '∩ (intersection) means in both. ∪ (union) means in either. A′ (complement) means everything in the universal set that is not in A.', null, null),
  ('usec-math-010', '["b","d","c","a"]'::jsonb, '2⁻¹ = 0.5, 2⁰ = 1, 2^(1/2) = √2 ≈ 1.41, and 2² = 4.', null, null),
  ('usec-amath-001', '{"value":12,"tolerance":0}'::jsonb, 'dy/dx = 2 × 3x = 6x. When x = 2, dy/dx = 12.', null, '[{"value":6,"why":"6x is the derivative; substitute x = 2 into it."},{"value":24,"why":"Bring the power down and reduce it by one: 3x² becomes 6x, not 6x²."}]'::jsonb),
  ('usec-amath-002', '"a"'::jsonb, 'Add one to the power and divide by the new power: 2 × x²/2 = x². Always add the constant c.', '{"b":"2 is the derivative of 2x; integration goes the other way.","c":"Keep the coefficient 2: 2 × x²/2 = x².","d":"Divide by the new power 2: the coefficient becomes 1."}'::jsonb, null),
  ('usec-amath-003', '{"value":5,"tolerance":0}'::jsonb, 'log₂ 32 asks: 2 to what power is 32? 2⁵ = 32, so the answer is 5.', null, '[{"value":16,"why":"16 is 32 ÷ 2; a logarithm asks for the power, not a division."}]'::jsonb),
  ('usec-amath-004', '{"value":210,"tolerance":0}'::jsonb, 'a = 3, d = 4. Sₙ = n/2 [2a + (n − 1)d] = 10/2 × [6 + 36] = 5 × 42 = 210.', null, '[{"value":39,"why":"39 is the 10th term; the question asks for the sum of the first 10 terms."},{"value":230,"why":"Use (n − 1)d = 9 × 4, not n × d = 10 × 4."}]'::jsonb),
  ('usec-amath-005', '"a"'::jsonb, 'The discriminant sits under the square root in the formula. A negative number has no real square root, so there are no real roots: the curve does not touch the x-axis.', '{"b":"Two equal roots happen when b² − 4ac = 0.","c":"Two different real roots happen when b² − 4ac > 0.","d":"The discriminant tells you how many roots, not their signs."}'::jsonb, null),
  ('usec-amath-006', '{"value":24,"tolerance":0}'::jsonb, '4 choices for the first place, 3 for the second, 2 for the third, 1 for the last: 4! = 4 × 3 × 2 × 1 = 24.', null, '[{"value":16,"why":"16 is 4 × 4; once a book is placed it cannot be used again, so the choices go 4, 3, 2, 1."},{"value":10,"why":"10 is 4 + 3 + 2 + 1; multiply the choices instead of adding."}]'::jsonb),
  ('usec-amath-007', '{"value":10,"tolerance":0}'::jsonb, '⁵C₂ = 5! ÷ (2! × 3!) = (5 × 4) ÷ 2 = 10.', null, '[{"value":20,"why":"20 is ⁵P₂, which counts each pair twice (AB and BA); divide by 2! because order does not matter."}]'::jsonb),
  ('usec-amath-008', '"true"'::jsonb, 'On the unit circle, a point at angle θ is (cos θ, sin θ). By Pythagoras, cos²θ + sin²θ = 1² = 1, for every angle.', '{"false":"This identity comes from Pythagoras'' theorem on the unit circle and holds for all angles, not just acute ones."}'::jsonb, null),
  ('usec-phy-001', '{"value":10,"tolerance":0,"unit":"m/s"}'::jsonb, 'v = u + at = 0 + 2 × 5 = 10 m/s.', null, '[{"value":7,"why":"Multiply acceleration by time; do not add them."},{"value":25,"why":"25 m is the distance travelled (½at²), not the velocity."}]'::jsonb),
  ('usec-phy-002', '{"value":6,"tolerance":0,"unit":"kg m/s"}'::jsonb, 'Momentum = mass × velocity = 2 × 3 = 6 kg m/s.', null, '[{"value":9,"why":"9 J is the kinetic energy (½mv²), not momentum."},{"value":5,"why":"Multiply mass and velocity; do not add them."}]'::jsonb),
  ('usec-phy-003', '"a"'::jsonb, 'Pressure is force per unit area. 1 pascal = 1 newton per square metre (N/m²).', '{"b":"The newton is the unit of force.","c":"The joule is the unit of energy and work.","d":"The watt is the unit of power."}'::jsonb, null),
  ('usec-phy-004', '{"value":200,"tolerance":0,"unit":"Pa"}'::jsonb, 'Pressure = force ÷ area = 100 ÷ 0.5 = 200 Pa.', null, '[{"value":50,"why":"50 is force × area; pressure divides force by area."}]'::jsonb),
  ('usec-phy-005', '["a","c","e"]'::jsonb, 'A vector has both size and direction. Velocity, force and acceleration all act in a direction.', '{"b":"Mass has size only, so it is a scalar.","d":"Temperature has size only, so it is a scalar."}'::jsonb, null),
  ('usec-phy-006', '{"value":460,"tolerance":0,"unit":"W"}'::jsonb, 'Power = voltage × current = 230 × 2 = 460 W.', null, '[{"value":115,"why":"115 is V ÷ I; electrical power is V × I."}]'::jsonb),
  ('usec-phy-007', '"a"'::jsonb, 'In a sound wave, particles vibrate back and forth along the direction the wave travels, making compressions and rarefactions. That is a longitudinal wave.', '{"b":"Light is an electromagnetic wave, which is transverse.","c":"Radio waves are electromagnetic, so transverse.","d":"X-rays are electromagnetic, so transverse."}'::jsonb, null),
  ('usec-phy-008', '["c","d","a","b"]'::jsonb, 'Gamma rays have the shortest wavelength, then X-rays, then visible light. Radio waves are the longest.', null, null),
  ('usec-phy-009', '{"value":100,"tolerance":0,"unit":"m/s"}'::jsonb, 'Wave speed v = f × λ = 50 × 2 = 100 m/s.', null, '[{"value":25,"why":"25 is f ÷ λ; multiply frequency by wavelength."}]'::jsonb),
  ('usec-phy-010', '{"a":"y","b":"z","c":"x"}'::jsonb, 'First law: inertia. Second law: F = ma. Third law: forces come in equal and opposite pairs.', null, null),
  ('usec-chem-001', '{"value":6,"tolerance":0}'::jsonb, 'Carbon''s proton (atomic) number is 6, so every carbon atom has 6 protons.', null, '[{"value":12,"why":"12 is the nucleon (mass) number of carbon-12: protons plus neutrons."}]'::jsonb),
  ('usec-chem-002', '{"value":44,"tolerance":0}'::jsonb, 'CO₂ has one carbon and two oxygen atoms: 12 + 2 × 16 = 44.', null, '[{"value":28,"why":"28 is CO with only one oxygen; CO₂ has two."}]'::jsonb),
  ('usec-chem-003', '"a"'::jsonb, 'Sodium gives an electron to chlorine, forming Na⁺ and Cl⁻ ions held together by electrostatic attraction: an ionic bond.', '{"b":"Covalent bonds share electrons, usually between non-metals.","c":"Metallic bonds hold atoms together inside a metal.","d":"Hydrogen bonds are weak forces between molecules, not inside salt."}'::jsonb, null),
  ('usec-chem-004', '["a","b","d"]'::jsonb, 'Lithium, sodium and potassium are in Group 1. Each has one electron in its outer shell.', '{"c":"Calcium is in Group 2 (alkaline earth metals).","e":"Chlorine is a Group 17 halogen, a non-metal."}'::jsonb, null),
  ('usec-chem-005', '"true"'::jsonb, 'Adding water lowers the concentration of hydrogen ions. Fewer H⁺ ions per volume means a higher pH, closer to 7 (but it never becomes alkaline).', '{"false":"pH depends on the concentration of H⁺ ions. Dilution spreads them out, so the pH rises towards 7."}'::jsonb, null),
  ('usec-chem-006', '"a"'::jsonb, 'Acid + reactive metal → salt + hydrogen: Zn + 2HCl → ZnCl₂ + H₂.', '{"b":"Salt + water comes from an acid reacting with a base, such as zinc oxide.","c":"No oxygen is involved, so no zinc oxide forms.","d":"Chlorine stays in the salt as chloride ions; no chlorine gas forms."}'::jsonb, null),
  ('usec-chem-007', '{"value":2,"tolerance":0,"unit":"mol"}'::jsonb, 'Moles = mass ÷ molar mass = 36 ÷ 18 = 2 mol.', null, '[{"value":648,"why":"648 is 36 × 18; divide the mass by the molar mass."},{"value":0.5,"why":"0.5 is 18 ÷ 36; put the mass on top."}]'::jsonb),
  ('usec-chem-008', '{"accept":["carbon dioxide","CO2"]}'::jsonb, 'Carbon dioxide reacts with limewater (calcium hydroxide solution) to form insoluble calcium carbonate, which makes it cloudy.', null, null),
  ('usec-chem-009', '["b","d","a","c"]'::jsonb, 'Reactivity decreases down Group 17: fluorine, chlorine, bromine, iodine. Larger atoms attract an extra electron less strongly.', null, null),
  ('usec-chem-010', '{"a":"y","b":"z","c":"x"}'::jsonb, 'Lemon juice is acidic (pH about 2), pure water is neutral (pH 7) and sodium hydroxide is a strong alkali (pH about 13).', null, null),
  ('usec-bio-001', '"a"'::jsonb, 'DNA (deoxyribonucleic acid) stores genetic instructions in the sequence of its bases.', '{"b":"ATP carries energy within cells, not genetic information.","c":"Glucose is a sugar used for energy.","d":"Haemoglobin is a protein that carries oxygen in red blood cells."}'::jsonb, null),
  ('usec-bio-002', '{"value":4,"tolerance":0}'::jsonb, 'Meiosis has two divisions, producing 4 daughter cells, each with half the original number of chromosomes.', null, '[{"value":2,"why":"2 daughter cells come from mitosis; meiosis divides twice."}]'::jsonb),
  ('usec-bio-003', '"a"'::jsonb, 'High temperatures change the shape of the enzyme''s active site, so the substrate no longer fits. The enzyme is denatured.', '{"b":"Enzymes speed up as it warms only up to the optimum (about 37 °C for human enzymes); beyond that they denature.","c":"Enzymes are proteins, and heat does not turn proteins into sugar.","d":"Temperature has a big effect on enzyme activity."}'::jsonb, null),
  ('usec-bio-004', '["a","b"]'::jsonb, 'The central nervous system is the brain and the spinal cord. Everything else is peripheral.', '{"c":"Sensory neurones belong to the peripheral nervous system.","d":"The heart is a muscular organ of the circulatory system.","e":"The retina is a sense organ tissue in the eye that sends signals to the brain."}'::jsonb, null),
  ('usec-bio-005', '["c","d","a","e","b"]'::jsonb, 'Nasal cavity → trachea (windpipe) → bronchus → bronchiole → alveolus, where gas exchange happens.', null, null),
  ('usec-bio-006', '"true"'::jsonb, 'Mature human red blood cells lose their nucleus, leaving more room for haemoglobin to carry oxygen.', '{"false":"Unlike most cells, mature human red blood cells have no nucleus; that space is used for haemoglobin."}'::jsonb, null),
  ('usec-bio-007', '{"a":"y","b":"z","c":"x"}'::jsonb, 'Insulin (lowers blood glucose) comes from the pancreas, adrenaline (fight or flight) from the adrenal glands, thyroxine (controls metabolism) from the thyroid.', null, null),
  ('usec-bio-008', '{"accept":["osmosis"]}'::jsonb, 'Osmosis is the diffusion of water across a partially permeable membrane, from where there is more free water (dilute) to where there is less (concentrated).', null, null),
  ('usec-hist-001', '"a"'::jsonb, 'Malaya became independent on 31 August 1957, now celebrated as Hari Merdeka.', '{"b":"16 September 1963 is when Malaysia was formed (Hari Malaysia).","c":"1 February 1948 is when the Federation of Malaya was set up, still under British protection.","d":"9 August 1965 is when Singapore left Malaysia."}'::jsonb, null),
  ('usec-hist-002', '{"value":1963,"tolerance":0}'::jsonb, 'Malaysia was formed on 16 September 1963 from Malaya, Sabah, Sarawak and Singapore.', null, '[{"value":1957,"why":"1957 is when Malaya became independent; Malaysia was formed six years later."}]'::jsonb),
  ('usec-hist-003', '"a"'::jsonb, 'Tunku Abdul Rahman, known as Bapa Kemerdekaan (Father of Independence), was the first Prime Minister.', '{"b":"Tun Abdul Razak was the second Prime Minister.","c":"Tun Hussein Onn was the third Prime Minister.","d":"Tun Dr Mahathir Mohamad was the fourth (and later the seventh) Prime Minister."}'::jsonb, null),
  ('usec-hist-004', '["b","d","a","c"]'::jsonb, 'Federation of Malaya (1948) → independence (1957) → formation of Malaysia (1963) → Singapore leaves (1965).', null, null)
